INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_ADJECTIVE','Unrung');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_ATTACKED_1','The chains have been removed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_BELFRY','Silent Belfry');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_BELFRY_HELP','Replaces Temple; retains all active CP Temple benefits and requirements. Adds +1 [ICON_CULTURE] Culture permanently and +1 [ICON_RESEARCH] Science per current Quietude stack (maximum +3). War removes conditional Science but keeps permanent Culture. Requires a Silent Belfry, not an ordinary Temple.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_BELFRY_PEDIA','A Silent Belfry is a temple built around an instrument that must never sound. Scholars work in its shadow; children learn its vow before they learn its history. The smallest bell is wrapped in felt. The greatest is bound with chains forged by generations who hoped never to see them removed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_BELFRY_STRATEGY','Build Silent Belfries during peace to turn Quietude into Science. At three stacks, a city with a Belfry gains +4 Culture and +3 Science beyond the ordinary Temple: +3 Culture from the ability, +1 permanent Culture and +3 conditional Science from the Belfry. War trades the peaceful economy for temporary defense.');
