INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_CIV','The Kingdom of the Unrung Bell');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_CIV5_HEADING_1','The Vow of Stillhaven');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_CIV5_TEXT_1','The Kingdom of the Unrung Bell is an original fictional civilization shaped by a terrible memory. Its ancestors survived an age of wars that ended when the Great Bell sounded. No chronicle agrees on what the sound did. All agree that the survivors vowed never to hear it again.[NEWLINE][NEWLINE]Stillhaven grew around the silent cathedral. Across the kingdom, contemplation became an institution: cloisters preserved learning, belfries supported scholars, and disciplined wardens guarded a peace measured in generations. Their prosperity rests on patience. Their last defense rests on breaking their oldest promise.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_CIV_PEDIA','The Kingdom of the Unrung Bell is an original fictional civilization shaped by a terrible memory. Its ancestors survived an age of wars that ended when the Great Bell sounded. No chronicle agrees on what the sound did. All agree that the survivors vowed never to hear it again.[NEWLINE][NEWLINE]Stillhaven grew around the silent cathedral. Across the kingdom, contemplation became an institution: cloisters preserved learning, belfries supported scholars, and disciplined wardens guarded a peace measured in generations. Their prosperity rests on patience. Their last defense rests on breaking their oldest promise.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_DAWN','Keeper Sable, Guardian of the Eternal Silence, your people await your wisdom.[NEWLINE][NEWLINE]Long ago, your ancestors lived beneath the shadow of endless war. Kingdoms rose and fell, armies marched across the earth, and the cries of the dying echoed through every valley.[NEWLINE][NEWLINE]Then came the Great Bell.[NEWLINE][NEWLINE]Its terrible sound brought the age of bloodshed to an end.[NEWLINE][NEWLINE]From that day forward, your people swore that it would never ring again.[NEWLINE][NEWLINE]Generations passed. The kingdom prospered. Its people learned to value knowledge, patience and the quiet beauty of peace.[NEWLINE][NEWLINE]But beyond your borders, the world remains restless.[NEWLINE][NEWLINE]Raise your Silent Belfries. Guard your sacred vow. Let wisdom flourish where violence once prevailed.[NEWLINE][NEWLINE]And should the world threaten your people once more...[NEWLINE][NEWLINE]May they never hear the bell.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_DEFEAT_1','At last... silence.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_DUMMY','Quietude');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_DUMMY_HELP','Automatic peaceful city yield. Cannot be constructed or purchased.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_FRIENDLY_1','There is room for you beside the quiet fire.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_GREETING_1','Welcome, traveler. Speak softly. Some things in this world are better left undisturbed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_GUARD','Vigil of the Bell');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_GUARD_HELP','+1 Sight and +15% friendly-land Combat Strength. Retained on upgrade. CP friendly lands include open borders; ranged attacks check the shooter tile.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_HOSTILE_1','Your footsteps disturb the cloister.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_LEADER','Keeper Sable');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_LEADER_PEDIA','Keeper Sable is the elderly Guardian of the Eternal Silence. Beneath black robes embroidered with silver bells she carries the keys to the cathedral chains. She governs through measured counsel, grants long audiences to scholars and answers military threats with few words.[NEWLINE][NEWLINE]Sable knows that a vow can protect a people only while the people survive to keep it. Her solemn authority comes from accepting responsibility for the one command she hopes never to give.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_NEUTRAL_1','The Keeper is listening.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_PEACE_1','Let the chains be fastened once more.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SABLE_HEADING_1','The Keeper and the Keys');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SABLE_LIVED','In the long vigil');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SABLE_NAME','Keeper Sable');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SABLE_SUBTITLE','Guardian of the Eternal Silence');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SABLE_TEXT_1','Keeper Sable is the elderly Guardian of the Eternal Silence. Beneath black robes embroidered with silver bells she carries the keys to the cathedral chains. She governs through measured counsel, grants long audiences to scholars and answers military threats with few words.[NEWLINE][NEWLINE]Sable knows that a vow can protect a people only while the people survive to keep it. Her solemn authority comes from accepting responsibility for the one command she hopes never to give.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SABLE_TITLES_1','Keeper of the Great Bell');
