INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SPY_4','Ash Vow');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SPY_5','Pale Key');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SPY_6','Hushed Step');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SPY_7','Silver Thread');
