INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_SPY_9','Night Cloister');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_STRATEGY','An advanced, human-only Culture / Science civilization. Complete five uninterrupted peaceful owner-turns per Quietude stack, up to three. Expand to spread Culture and build Silent Belfries for Science. A qualifying war immediately consumes the economy for a five-window land defense surge. Defend patiently; additional declarations cannot renew the Toll. Complete peace is necessary before Quietude can grow again.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TOLL_I','The Great Toll I');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TOLL_II','The Great Toll II');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TOLL_III','The Great Toll III');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TOLL_III_HELP','+15% friendly-land Combat Strength during the Great Toll. Ends at complete peace or after five full owner-turn windows. CP friendly lands include open borders; ranged attacks check the shooter tile.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TOLL_II_HELP','+10% friendly-land Combat Strength during the Great Toll. Ends at complete peace or after five full owner-turn windows. CP friendly lands include open borders; ranged attacks check the shooter tile.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TOLL_I_HELP','+5% friendly-land Combat Strength during the Great Toll. Ends at complete peace or after five full owner-turn windows. CP friendly lands include open borders; ranged attacks check the shooter tile.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TRADE_1','Let this agreement be kept without fanfare.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TRAIT','Silence Before the Storm');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_TRAIT_HELP','Every 5 consecutive peaceful owner-turns earn Quietude (maximum 3): +1 [ICON_CULTURE] Culture per city per stack. War with a civilization or city-state consumes Quietude for the Great Toll: +5%/+10%/+15% friendly-land combat for land military units through the next 5 full owner-turn windows. Additional wars never refresh it; complete peace ends it. Barbarians do not interrupt peace. CP friendly lands include open borders; ranged attacks check the shooter tile. See guide.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_UNIT','Bellwarden');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_UNIT_HELP','Replaces Pikeman; retains the active CP Pikeman properties. Permanent +1 Sight and +15% friendly-land Combat Strength, retained on upgrade. Stacks additively with the Great Toll. CP friendly lands include open-border territory; ranged upgrades check their own tile.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_UNIT_PEDIA','The Bellwardens are the sworn military order of the sacred towers. Each learns to read a horizon before drawing a weapon, and each knows the chain that must be broken only once. Their pikes and armor follow ordinary Pikeman models; their long vigil survives every later change of equipment.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_UNIT_STRATEGY','Guard the kingdom with Bellwardens while Quietude grows. Their inherited Pikeman training, additional Sight and permanent friendly-land bonus support defense. Upgrade normally without losing the unique promotion. During Great Toll III their two unique modifiers total +30%.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_UNRUNG_WAR_1','You have mistaken our silence for weakness. That was your final mistake.');
